CREATE TABLE `comensales` (`id_comensal` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_comensal`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `tipos_plato` (`id_tipo_plato` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_tipo_plato`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `platos` (`id_plato` INT NOT NULL AUTO_INCREMENT, `id_tipo_plato` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `precio` DECIMAL(11,2) NOT NULL, `porciones` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_plato`), KEY `idx_recurso_categoria` (`id_tipo_plato`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_tipo_plato`) REFERENCES `tipos_plato` (`id_tipo_plato`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `restaurantes` (`id_restaurante` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_restaurante`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `meseros` (`id_mesero` INT NOT NULL AUTO_INCREMENT, `id_restaurante` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_mesero`), KEY `idx_empleado_sede` (`id_restaurante`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_restaurante`) REFERENCES `restaurantes` (`id_restaurante`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `comandas` (`id_comanda` INT NOT NULL AUTO_INCREMENT, `id_comensal` INT NOT NULL, `id_mesero` INT NOT NULL, `id_restaurante` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_comanda`), KEY `idx_operacion_persona` (`id_comensal`), KEY `idx_operacion_empleado` (`id_mesero`), KEY `idx_operacion_sede` (`id_restaurante`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_comensal`) REFERENCES `comensales` (`id_comensal`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_mesero`) REFERENCES `meseros` (`id_mesero`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_restaurante`) REFERENCES `restaurantes` (`id_restaurante`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `platos_comanda` (`id_plato_comanda` INT NOT NULL AUTO_INCREMENT, `id_comanda` INT NOT NULL, `id_plato` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_plato_comanda`), KEY `idx_detalle_operacion` (`id_comanda`), KEY `idx_detalle_recurso` (`id_plato`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_comanda`) REFERENCES `comandas` (`id_comanda`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_plato`) REFERENCES `platos` (`id_plato`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_comanda` (`id_pago_comanda` INT NOT NULL AUTO_INCREMENT, `id_comanda` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_comanda`), KEY `idx_pago_operacion` (`id_comanda`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_comanda`) REFERENCES `comandas` (`id_comanda`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `comentarios` (`id_comentario` INT NOT NULL AUTO_INCREMENT, `id_comanda` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_comentario`), KEY `idx_evento_operacion` (`id_comanda`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_comanda`) REFERENCES `comandas` (`id_comanda`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
